def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    lines = []
    for r, row in enumerate(grid):
        if row[0] != 0 and all(v == row[0] for v in row):
            lines.append(("r", r))
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            lines.append(("c", c))
    for axis, i in lines:
        if axis == "r":
            out[i] = [2] * w
        else:
            for r in range(h):
                out[r][i] = 2
    return out

